// Des: Command cont: contact book backup, export, forget, verify, restore
// Flo: no word = counts, with --live also the local encrypted backup and its check > export writes vCard (default) or CSV > forget <phone or id> deletes the contact and rewrites every backup copy > drop removes all private persons > key prints the key once
// I/O: Ctx (config, db, key folder) > one line or JSON, exit code; writing commands are dry-run unless --live; no network except the cloud scrub of forget and drop
// ===================================================================
const std = @import("std"); const ctx3 = @import("ct-ctrl-ctxz.zig"); const cpic = @import("ct-ctrl-cpic.zig"); const cstr = @import("st-carz-stor.zig"); const stor = @import("st-cont-stor.zig"); const back = @import("sy-cont-back.zig"); const cryp = @import("ut-cryp-aead.zig"); const live = @import("nt-vend-live.zig"); const pipe = @import("ru-page-fetc.zig"); const pexp = @import("ut-path-expa.zig"); const sqli = @import("st-stor-sqli.zig");
const CF = .{ .part = ".part" };
const Outp = struct { tots: i64, deal: i64, priv: i64, phon: i64, mail: i64, addr: i64, mask: i64, latr: u32, fils: u32, bads: u32 };
fn keyzGetz(ctx2: *const ctx3.Ctxz) ![cryp.CF.keyb]u8 { const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return error.BadConfig; return cryp.keyzLoad(ctx2.allo, ctx2.iozz, try std.fs.path.join(ctx2.allo, &.{ keyd, "cont.key" })); }
fn scal(dbzz: *sqli.Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
fn scruAllz(ctx2: *const ctx3.Ctxz, keyz: [cryp.CF.keyb]u8, cidz: []const []const u8) !u32 { var cont: u32 = try back.backScru(ctx2.allo, ctx2.iozz, ctx2.dirz, null, keyz, cidz); const keyd = pexp.pathExpa(ctx2.allo, ctx2.home, ctx2.conf.vend_keyz_dirz) catch return cont; var lvzz: live.Live = .{ .time_mill = ctx2.conf.fetc_time_seco * 1000 }; const hand = cpic.handMake(ctx2, lvzz.send(), keyd) catch return cont; for (hand.stos) |item| { cont += back.backScru(ctx2.allo, ctx2.iozz, ctx2.dirz, item.store, keyz, cidz) catch 0; } return cont; }
fn runzExpo(ctx2: *const ctx3.Ctxz, dbzz: *sqli.Dbzz) !u8 { const body = if (std.mem.eql(u8, ctx2.args.fmtz, "csv")) try stor.csvzBuil(ctx2.allo, dbzz) else try stor.vcrdBuil(ctx2.allo, dbzz); if (ctx2.args.outz.len == 0) { try std.Io.File.stdout().writeStreamingAll(ctx2.iozz, body); return 0; } const temp = try std.fmt.allocPrint(ctx2.allo, "{s}{s}", .{ ctx2.args.outz, CF.part }); const cwdz = std.Io.Dir.cwd(); var filz = try cwdz.createFile(ctx2.iozz, temp, .{}); filz.writeStreamingAll(ctx2.iozz, body) catch |err3| { filz.close(ctx2.iozz); return err3; }; filz.close(ctx2.iozz); try cwdz.rename(temp, cwdz, ctx2.args.outz, ctx2.iozz); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "exported {d} contacts to {s}", .{ try scal(dbzz, "SELECT count(*) FROM cont;"), ctx2.args.outz })); return 0; }
pub fn runzCont(ctx2: *const ctx3.Ctxz) !u8 { if (!ctx3.dbzzHave(ctx2)) { try ctx3.outz(ctx2, "no contacts yet"); return 0; } if (!ctx2.conf.cont_enab) { try ctx3.outz(ctx2, "contacts are off (cont_enab is false)"); return 0; } var dbzz = try ctx3.dbzzOpen(ctx2); defer dbzz.close(); const subz = ctx2.args.urlz; const nowz = pipe.nowzMill(ctx2.iozz); const livz = ctx2.args.live;
    if (std.mem.eql(u8, subz, "export")) return runzExpo(ctx2, &dbzz); const keyz = try keyzGetz(ctx2); var stoz = try cstr.storOpen(&dbzz, nowz);
    if (std.mem.eql(u8, subz, "key")) { const hexz = std.fmt.bytesToHex(keyz, .lower); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "backup key (keep an offline copy, without it the backups cannot be opened): {s}", .{hexz})); return 0; }
    if (std.mem.eql(u8, subz, "restore")) { if (ctx2.args.rest.len == 0) return error.BadUsage; if (!livz) { try ctx3.outz(ctx2, "dry-run | would load contacts from the backup file | add --live to run"); return 0; } const cont = try back.backRest(ctx2.allo, ctx2.iozz, &dbzz, keyz, ctx2.args.rest); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "restored {d} contacts", .{cont})); return 0; }
    if (std.mem.eql(u8, subz, "forget")) { if (ctx2.args.rest.len == 0) return error.BadUsage; const cidz = try stor.contLook(&stoz, ctx2.allo, ctx2.args.rest); if (!livz) { try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} contact(s) match | add --live to delete them and rewrite every backup", .{cidz.len})); return 0; } const gone = try stor.contForg(&stoz, ctx2.allo, ctx2.args.rest); const fils = try scruAllz(ctx2, keyz, cidz); _ = try back.backLoca(ctx2.allo, ctx2.iozz, &dbzz, ctx2.dirz, keyz, nowz, ctx2.conf.cont_week_keep); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "forgot {d} contact(s), rewrote {d} backup file(s)", .{ gone, fils })); return 0; }
    if (std.mem.eql(u8, subz, "drop")) { const priv = try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='private';"); if (!livz) { try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dry-run | {d} private contact(s) would be deleted everywhere | add --live to run", .{priv})); return 0; } var idzz: std.ArrayList([]const u8) = .empty; { var selz = try dbzz.prep("SELECT cidz FROM cont WHERE kind='private';"); defer selz.fini(); while (try selz.step()) try idzz.append(ctx2.allo, try ctx2.allo.dupe(u8, selz.colzText(0))); } const gone = try stor.contDrop(&stoz, ctx2.allo); const fils = try scruAllz(ctx2, keyz, idzz.items); _ = try back.backLoca(ctx2.allo, ctx2.iozz, &dbzz, ctx2.dirz, keyz, nowz, ctx2.conf.cont_week_keep); try ctx3.outz(ctx2, try std.fmt.allocPrint(ctx2.allo, "dropped {d} private contact(s), rewrote {d} backup file(s)", .{ gone, fils })); return 0; }
    if (subz.len > 0 and !std.mem.eql(u8, subz, "verify")) return error.BadUsage; if (livz and subz.len == 0) _ = try back.backLoca(ctx2.allo, ctx2.iozz, &dbzz, ctx2.dirz, keyz, nowz, ctx2.conf.cont_week_keep);
    const verz = try back.backVeri(ctx2.allo, ctx2.iozz, ctx2.dirz, keyz); const outp: Outp = .{ .tots = try scal(&dbzz, "SELECT count(*) FROM cont;"), .deal = try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='dealer';"), .priv = try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='private';"), .phon = try scal(&dbzz, "SELECT count(*) FROM cont WHERE phon<>'';"), .mail = try scal(&dbzz, "SELECT count(*) FROM cont WHERE mail<>'';"), .addr = try scal(&dbzz, "SELECT count(*) FROM cont WHERE addr<>'';"), .mask = try scal(&dbzz, "SELECT count(*) FROM cont WHERE mask=1;"), .latr = verz.late, .fils = verz.fils, .bads = verz.bads };
    const plai = try std.fmt.allocPrint(ctx2.allo, "contacts {s} | {d} total ({d} dealer, {d} private) | with phone {d} (masked {d}), email {d}, address {d} | backups: {d} file(s), latest holds {d}, {d} bad{s}", .{ if (subz.len > 0) "verify" else if (livz) "live" else "dry-run", outp.tots, outp.deal, outp.priv, outp.phon, outp.mask, outp.mail, outp.addr, outp.fils, outp.latr, outp.bads, if (!livz and subz.len == 0) " | add --live to back up now" else "" }); try ctx3.outz(ctx2, try ctx3.jsonOrzz(ctx2, outp, plai)); return if (outp.bads > 0) 1 else 0; }
